DROP TABLE IF EXISTS `pre_installation_steps`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `pre_installation_steps` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `pre_inst_id` int(11) NOT NULL COMMENT 'FK to pre_installation_forms.formID',
  `step_number` int(11) NOT NULL,
  `step_name` varchar(255) NOT NULL,
  `description` text DEFAULT NULL,
  `duration_minutes` int(11) DEFAULT 0,
  `assigned_to` varchar(255) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_pre_inst_steps_pre_inst_id` (`pre_inst_id`),
  KEY `idx_pre_inst_steps_step_number` (`step_number`),
  CONSTRAINT `fk_pre_inst_steps_pre_inst` FOREIGN KEY (`pre_inst_id`) REFERENCES `pre_installation_forms` (`formID`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Production steps for each pre-installation (linked to production orders)';
