DROP TABLE IF EXISTS `product_list`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `product_list` (
  `productID` int(11) NOT NULL,
  `sku` varchar(100) DEFAULT NULL,
  `name` varchar(255) NOT NULL,
  `description` text DEFAULT NULL,
  `Capacity (kVA)` varchar(225) NOT NULL,
  `MCB` varchar(225) NOT NULL,
  `Size (WxLxH) cm.` varchar(225) NOT NULL,
  `Weight` varchar(225) NOT NULL,
  `price` decimal(12,2) DEFAULT 0.00,
  `Pin_VAT` decimal(12,2) DEFAULT 0.00,
  `unit` varchar(50) DEFAULT 'unit',
  `TFC_duty` varchar(225) DEFAULT '0.00',
  `Installation` varchar(225) DEFAULT '0.00',
  `Profit` decimal(12,2) DEFAULT 0.00,
  `commission` decimal(12,2) DEFAULT 0.00,
  `category` varchar(100) DEFAULT NULL,
